SELECT n.name, mi1.info, MIN(t.production_year), MAX(t.production_year) FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n WHERE t.id = ci.movie_id AND t.id = mi1.movie_id AND mi1.info_type_id = it1.id AND t.kind_id = kt.id AND ci.person_id = n.id AND ci.movie_id = mi1.movie_id AND ci.role_id = rt.id AND (it1.id IN ('2','8')) AND (mi1.info IN ('Australia','Black and White','Brazil','Canada','Color','Finland','France','Germany','Hong Kong','India','Netherlands','Philippines','Spain','Taiwan','UK','USA','West Germany')) AND (UPPER(n.name) LIKE UPPER('%pen%')) AND (kt.kind IN ('movie','tv movie')) AND (rt.role IN ('director','editor','miscellaneous crew','producer','production designer')) GROUP BY HASH(SUBSTRING(mi1.info FROM 1 FOR 8000) || '#' || SUBSTRING(n.name FROM 1 FOR 8000)), 2, 1 
